package config

import (
	"encoding/json"

	"github.com/spf13/viper"
)

// cheers up the unparam linter
var _ defaulter = (*TracingConfig)(nil)

// TracingConfig contains fields, which configure tracing telemetry
// output destinations.
type TracingConfig struct {
	Enabled  bool                `json:"enabled" mapstructure:"enabled" yaml:"enabled"`
	Exporter TracingExporter     `json:"exporter,omitempty" mapstructure:"exporter" yaml:"exporter,omitempty"`
	Jaeger   JaegerTracingConfig `json:"jaeger,omitempty" mapstructure:"jaeger" yaml:"jaeger,omitempty"`
	Zipkin   ZipkinTracingConfig `json:"zipkin,omitempty" mapstructure:"zipkin" yaml:"zipkin,omitempty"`
	OTLP     OTLPTracingConfig   `json:"otlp,omitempty" mapstructure:"otlp" yaml:"otlp,omitempty"`
}

func (c *TracingConfig) setDefaults(v *viper.Viper) error {
	v.SetDefault("tracing", map[string]any{
		"enabled":  false,
		"exporter": TracingJaeger,
		"jaeger": map[string]any{
			"host": "localhost",
			"port": 6831,
		},
		"zipkin": map[string]any{
			"endpoint": "http://localhost:9411/api/v2/spans",
		},
		"otlp": map[string]any{
			"endpoint": "localhost:4317",
		},
	})

	return nil
}

func (c *TracingConfig) deprecations(v *viper.Viper) []deprecated {
	var deprecations []deprecated

	if v.GetString("tracing.exporter") == TracingJaeger.String() && v.GetBool("tracing.enabled") {
		deprecations = append(deprecations, "tracing.exporter.jaeger")
	}

	return deprecations
}

// IsZero returns true if the tracing config is not enabled.
// This is used for marshalling to YAML for `config init`.
func (c TracingConfig) IsZero() bool {
	return !c.Enabled
}

// TracingExporter represents the supported tracing exporters.
// TODO: can we use a string here instead?
type TracingExporter uint8

func (e TracingExporter) String() string {
	return tracingExporterToString[e]
}

func (e TracingExporter) MarshalJSON() ([]byte, error) {
	return json.Marshal(e.String())
}

func (e TracingExporter) MarshalYAML() (interface{}, error) {
	return e.String(), nil
}

const (
	_ TracingExporter = iota
	// TracingJaeger ...
	TracingJaeger
	// TracingZipkin ...
	TracingZipkin
	// TracingOTLP ...
	TracingOTLP
)

var (
	tracingExporterToString = map[TracingExporter]string{
		TracingJaeger: "jaeger",
		TracingZipkin: "zipkin",
		TracingOTLP:   "otlp",
	}

	stringToTracingExporter = map[string]TracingExporter{
		"jaeger": TracingJaeger,
		"zipkin": TracingZipkin,
		"otlp":   TracingOTLP,
	}
)

// JaegerTracingConfig contains fields, which configure
// Jaeger span and tracing output destination.
type JaegerTracingConfig struct {
	Host string `json:"host,omitempty" mapstructure:"host" yaml:"host,omitempty"`
	Port int    `json:"port,omitempty" mapstructure:"port" yaml:"port,omitempty"`
}

// ZipkinTracingConfig contains fields, which configure
// Zipkin span and tracing output destination.
type ZipkinTracingConfig struct {
	Endpoint string `json:"endpoint,omitempty" mapstructure:"endpoint" yaml:"endpoint,omitempty"`
}

// OTLPTracingConfig contains fields, which configure
// OTLP span and tracing output destination.
type OTLPTracingConfig struct {
	Endpoint string            `json:"endpoint,omitempty" mapstructure:"endpoint" yaml:"endpoint,omitempty"`
	Headers  map[string]string `json:"headers,omitempty" mapstructure:"headers" yaml:"headers,omitempty"`
}
package config

import (
	"context"
	"encoding/json"
	"fmt"
	"io/fs"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"reflect"
	"slices"
	"strings"
	"time"

	"github.com/mitchellh/mapstructure"
	"github.com/spf13/viper"
	"go.flipt.io/flipt/internal/storage/fs/object"
	"gocloud.dev/blob"
	"golang.org/x/exp/constraints"
)

const Version = "1.0"
const EnvPrefix = "FLIPT"

var DecodeHooks = []mapstructure.DecodeHookFunc{
	mapstructure.StringToTimeDurationHookFunc(),
	stringToSliceHookFunc(),
	stringToEnumHookFunc(stringToLogEncoding),
	stringToEnumHookFunc(stringToCacheBackend),
	stringToEnumHookFunc(stringToTracingExporter),
	stringToEnumHookFunc(stringToScheme),
	stringToEnumHookFunc(stringToDatabaseProtocol),
	stringToEnumHookFunc(stringToAuthMethod),
}

// Config contains all of Flipts configuration needs.
//
// The root of this structure contains a collection of sub-configuration categories.
//
// Each sub-configuration (e.g. LogConfig) optionally implements either or both of
// the defaulter or validator interfaces.
// Given the sub-config implements a `setDefaults(*viper.Viper) []string` method
// then this will be called with the viper context before unmarshalling.
// This allows the sub-configuration to set any appropriate defaults.
// Given the sub-config implements a `validate() error` method
// then this will be called after unmarshalling, such that the function can emit
// any errors derived from the resulting state of the configuration.
type Config struct {
	Version        string               `json:"version,omitempty" mapstructure:"version,omitempty" yaml:"version,omitempty"`
	Audit          AuditConfig          `json:"audit,omitempty" mapstructure:"audit" yaml:"audit,omitempty"`
	Authentication AuthenticationConfig `json:"authentication,omitempty" mapstructure:"authentication" yaml:"authentication,omitempty"`
	Cache          CacheConfig          `json:"cache,omitempty" mapstructure:"cache" yaml:"cache,omitempty"`
	Cors           CorsConfig           `json:"cors,omitempty" mapstructure:"cors" yaml:"cors,omitempty"`
	Database       DatabaseConfig       `json:"db,omitempty" mapstructure:"db" yaml:"db,omitempty"`
	Diagnostics    DiagnosticConfig     `json:"diagnostics,omitempty" mapstructure:"diagnostics" yaml:"diagnostics,omitempty"`
	Experimental   ExperimentalConfig   `json:"experimental,omitempty" mapstructure:"experimental" yaml:"experimental,omitempty"`
	Log            LogConfig            `json:"log,omitempty" mapstructure:"log" yaml:"log,omitempty"`
	Meta           MetaConfig           `json:"meta,omitempty" mapstructure:"meta" yaml:"meta,omitempty"`
	Analytics      AnalyticsConfig      `json:"analytics,omitempty" mapstructure:"analytics" yaml:"analytics,omitempty"`
	Server         ServerConfig         `json:"server,omitempty" mapstructure:"server" yaml:"server,omitempty"`
	Storage        StorageConfig        `json:"storage,omitempty" mapstructure:"storage" yaml:"storage,omitempty"`
	Tracing        TracingConfig        `json:"tracing,omitempty" mapstructure:"tracing" yaml:"tracing,omitempty"`
	UI             UIConfig             `json:"ui,omitempty" mapstructure:"ui" yaml:"ui,omitempty"`
}

type Result struct {
	Config   *Config
	Warnings []string
}

// Dir returns the default root directory for Flipt configuration
func Dir() (string, error) {
	configDir, err := os.UserConfigDir()
	if err != nil {
		return "", fmt.Errorf("getting user config dir: %w", err)
	}

	return filepath.Join(configDir, "flipt"), nil
}

func Load(path string) (*Result, error) {
	v := viper.New()
	v.SetEnvPrefix(EnvPrefix)
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	var cfg *Config

	if path == "" {
		cfg = Default()
	} else {
		cfg = &Config{}
		file, err := getConfigFile(context.Background(), path)
		if err != nil {
			return nil, err
		}
		defer file.Close()
		stat, err := file.Stat()
		if err != nil {
			return nil, err
		}

		// reimplement logic from v.ReadInConfig()
		v.SetConfigFile(stat.Name())
		ext := filepath.Ext(stat.Name())
		if len(ext) > 1 {
			ext = ext[1:]
		}
		if !slices.Contains(viper.SupportedExts, ext) {
			return nil, viper.UnsupportedConfigError(ext)
		}
		if err := v.ReadConfig(file); err != nil {
			return nil, err
		}
	}

	var (
		result      = &Result{Config: cfg}
		deprecators []deprecator
		defaulters  []defaulter
		validators  []validator
	)

	f := func(field any) {
		// for-each deprecator implementing field we collect
		// them up and return them to be run before unmarshalling and before setting defaults.
		if deprecator, ok := field.(deprecator); ok {
			deprecators = append(deprecators, deprecator)
		}

		// for-each defaulter implementing fields we invoke
		// setting any defaults during this prepare stage
		// on the supplied viper.
		if defaulter, ok := field.(defaulter); ok {
			defaulters = append(defaulters, defaulter)
		}

		// for-each validator implementing field we collect
		// them up and return them to be validated after
		// unmarshalling.
		if validator, ok := field.(validator); ok {
			validators = append(validators, validator)
		}
	}

	// invoke the field visitor on the root config firsts
	root := reflect.ValueOf(cfg).Interface()
	f(root)

	// these are reflected config top-level types for fields where
	// they have been marked as experimental and their associated
	// flag has enabled set to false.
	var skippedTypes []reflect.Type

	val := reflect.ValueOf(cfg).Elem()
	for i := 0; i < val.NumField(); i++ {
		// search for all expected env vars since Viper cannot
		// infer when doing Unmarshal + AutomaticEnv.
		// see: https://github.com/spf13/viper/issues/761
		structField := val.Type().Field(i)
		if exp := structField.Tag.Get("experiment"); exp != "" {
			// TODO(georgemac): register target for skipping
			if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
				skippedTypes = append(skippedTypes, structField.Type)
			}
		}

		key := fieldKey(structField)
		bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)

		field := val.Field(i).Addr().Interface()
		f(field)
	}

	// run any deprecations checks
	for _, deprecator := range deprecators {
		warnings := deprecator.deprecations(v)
		for _, warning := range warnings {
			result.Warnings = append(result.Warnings, warning.Message())
		}
	}

	// run any defaulters
	for _, defaulter := range defaulters {
		if err := defaulter.setDefaults(v); err != nil {
			return nil, err
		}
	}

	if err := v.Unmarshal(cfg, viper.DecodeHook(
		mapstructure.ComposeDecodeHookFunc(
			append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
		),
	)); err != nil {
		return nil, err
	}

	// run any validation steps
	for _, validator := range validators {
		if err := validator.validate(); err != nil {
			return nil, err
		}
	}

	return result, nil
}

// getConfigFile provides a file from different type of storage.
func getConfigFile(ctx context.Context, path string) (fs.File, error) {
	u, err := url.Parse(path)
	if err != nil {
		return nil, err
	}

	if slices.Contains(object.SupportedSchemes(), u.Scheme) {
		key := strings.TrimPrefix(u.Path, "/")
		u.Path = ""
		bucket, err := object.OpenBucket(ctx, u)
		if err != nil {
			return nil, err
		}
		defer bucket.Close()
		bucket.SetIOFSCallback(func() (context.Context, *blob.ReaderOptions) { return ctx, nil })
		return bucket.Open(key)
	}

	// assumes that the local file is used
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return file, nil
}

type defaulter interface {
	setDefaults(v *viper.Viper) error
}

type validator interface {
	validate() error
}

type deprecator interface {
	deprecations(v *viper.Viper) []deprecated
}

// fieldKey returns the name to be used when deriving a fields env var key.
// If marked as squash the key will be the empty string.
// Otherwise, it is derived from the lowercase name of the field.
func fieldKey(field reflect.StructField) string {
	if tag := field.Tag.Get("mapstructure"); tag != "" {
		tag, attr, ok := strings.Cut(tag, ",")
		if !ok || attr == "squash" || attr == "omitempty" {
			return tag
		}
	}

	return strings.ToLower(field.Name)

package tracing

import (
	"context"
	"fmt"
	"net/url"
	"strconv"
	"sync"

	"go.flipt.io/flipt/internal/config"
	"go.opentelemetry.io/otel/exporters/jaeger"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracegrpc"
	"go.opentelemetry.io/otel/exporters/otlp/otlptrace/otlptracehttp"
	"go.opentelemetry.io/otel/exporters/zipkin"
	"go.opentelemetry.io/otel/sdk/resource"
	tracesdk "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
)

// newResource constructs a trace resource with Flipt-specific attributes.
// It incorporates schema URL, service name, service version, and OTLP environment data
func newResource(ctx context.Context, fliptVersion string) (*resource.Resource, error) {
	return resource.New(ctx, resource.WithSchemaURL(semconv.SchemaURL), resource.WithAttributes(
		semconv.ServiceNameKey.String("flipt"),
		semconv.ServiceVersionKey.String(fliptVersion),
	),
		resource.WithFromEnv(),
	)
}

// NewProvider creates a new TracerProvider configured for Flipt tracing.
func NewProvider(ctx context.Context, fliptVersion string) (*tracesdk.TracerProvider, error) {
	traceResource, err := newResource(ctx, fliptVersion)
	if err != nil {
		return nil, err
	}
	return tracesdk.NewTracerProvider(
		tracesdk.WithResource(traceResource),
		tracesdk.WithSampler(tracesdk.AlwaysSample()),
	), nil
}

var (
	traceExpOnce sync.Once
	traceExp     tracesdk.SpanExporter
	traceExpFunc func(context.Context) error = func(context.Context) error { return nil }
	traceExpErr  error
)

// GetExporter retrieves a configured tracesdk.SpanExporter based on the provided configuration.
// Supports Jaeger, Zipkin and OTLP
func GetExporter(ctx context.Context, cfg *config.TracingConfig) (tracesdk.SpanExporter, func(context.Context) error, error) {
	traceExpOnce.Do(func() {
		switch cfg.Exporter {
		case config.TracingJaeger:
			traceExp, traceExpErr = jaeger.New(jaeger.WithAgentEndpoint(
				jaeger.WithAgentHost(cfg.Jaeger.Host),
				jaeger.WithAgentPort(strconv.FormatInt(int64(cfg.Jaeger.Port), 10)),
			))
		case config.TracingZipkin:
			traceExp, traceExpErr = zipkin.New(cfg.Zipkin.Endpoint)
		case config.TracingOTLP:
			u, err := url.Parse(cfg.OTLP.Endpoint)
			if err != nil {
				traceExpErr = fmt.Errorf("parsing otlp endpoint: %w", err)
				return
			}

			var client otlptrace.Client
			switch u.Scheme {
			case "http", "https":
				client = otlptracehttp.NewClient(
					otlptracehttp.WithEndpoint(u.Host+u.Path),
					otlptracehttp.WithHeaders(cfg.OTLP.Headers),
				)
			case "grpc":
				// TODO: support additional configuration options
				client = otlptracegrpc.NewClient(
					otlptracegrpc.WithEndpoint(u.Host+u.Path),
					otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlptracegrpc.WithInsecure(),
				)
			default:
				// because of url parsing ambiguity, we'll assume that the endpoint is a host:port with no scheme
				client = otlptracegrpc.NewClient(
					otlptracegrpc.WithEndpoint(cfg.OTLP.Endpoint),
					otlptracegrpc.WithHeaders(cfg.OTLP.Headers),
					// TODO: support TLS
					otlptracegrpc.WithInsecure(),
				)
			}

			traceExp, traceExpErr = otlptrace.New(ctx, client)
			traceExpFunc = func(ctx context.Context) error {
				return traceExp.Shutdown(ctx)
			}

		default:
			traceExpErr = fmt.Errorf("unsupported tracing exporter: %s", cfg.Exporter)
			return
		}
	})

	return traceExp, traceExpFunc, traceExpErr
}
package tracing

import (
	"context"
	"errors"
	"sync"
	"testing"

	"github.com/stretchr/testify/assert"
	"go.flipt.io/flipt/internal/config"
	"go.opentelemetry.io/otel/attribute"
	semconv "go.opentelemetry.io/otel/semconv/v1.4.0"
)

func TestNewResourceDefault(t *testing.T) {
	tests := []struct {
		name string
		envs map[string]string
		want []attribute.KeyValue
	}{
		{
			name: "with envs",
			envs: map[string]string{
				"OTEL_SERVICE_NAME":        "myservice",
				"OTEL_RESOURCE_ATTRIBUTES": "key1=value1",
			},
			want: []attribute.KeyValue{
				attribute.Key("key1").String("value1"),
				semconv.ServiceNameKey.String("myservice"),
				semconv.ServiceVersionKey.String("test"),
			},
		},
		{
			name: "default",
			envs: map[string]string{},
			want: []attribute.KeyValue{
				semconv.ServiceNameKey.String("flipt"),
				semconv.ServiceVersionKey.String("test"),
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for k, v := range tt.envs {
				t.Setenv(k, v)
			}
			r, err := newResource(context.Background(), "test")
			assert.NoError(t, err)
			assert.Equal(t, tt.want, r.Attributes())
		})
	}
}

func TestGetTraceExporter(t *testing.T) {
	tests := []struct {
		name    string
		cfg     *config.TracingConfig
		wantErr error
	}{
		{
			name: "Jaeger",
			cfg: &config.TracingConfig{
				Exporter: config.TracingJaeger,
				Jaeger: config.JaegerTracingConfig{
					Host: "localhost",
					Port: 6831,
				},
			},
		},
		{
			name: "Zipkin",
			cfg: &config.TracingConfig{
				Exporter: config.TracingZipkin,
				Zipkin: config.ZipkinTracingConfig{
					Endpoint: "http://localhost:9411/api/v2/spans",
				},
			},
		},
		{
			name: "OTLP HTTP",
			cfg: &config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP: config.OTLPTracingConfig{
					Endpoint: "http://localhost:4317",
					Headers:  map[string]string{"key": "value"},
				},
			},
		},
		{
			name: "OTLP HTTPS",
			cfg: &config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP: config.OTLPTracingConfig{
					Endpoint: "https://localhost:4317",
					Headers:  map[string]string{"key": "value"},
				},
			},
		},
		{
			name: "OTLP GRPC",
			cfg: &config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP: config.OTLPTracingConfig{
					Endpoint: "grpc://localhost:4317",
					Headers:  map[string]string{"key": "value"},
				},
			},
		},
		{
			name: "OTLP default",
			cfg: &config.TracingConfig{
				Exporter: config.TracingOTLP,
				OTLP: config.OTLPTracingConfig{
					Endpoint: "localhost:4317",
					Headers:  map[string]string{"key": "value"},
				},
			},
		},
		{
			name:    "Unsupported Exporter",
			cfg:     &config.TracingConfig{},
			wantErr: errors.New("unsupported tracing exporter: "),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			traceExpOnce = sync.Once{}
			exp, expFunc, err := GetExporter(context.Background(), tt.cfg)
			if tt.wantErr != nil {
				assert.EqualError(t, err, tt.wantErr.Error())
				return
			}
			t.Cleanup(func() {
				err := expFunc(context.Background())
				assert.NoError(t, err)
			})
			assert.NoError(t, err)
			assert.NotNil(t, exp)
			assert.NotNil(t, expFunc)

		})
	}
}

